"""Independent receipt fixtures, never generated by the collector under test.

Only the expensive pinned-base reader is mocked in unit fixtures. Real source
codec/load, verifier code hashes, request checks and immutable handles remain
active. Optional integration uses the real pinned ZIP with an absent token.
"""
from __future__ import annotations

from collections import Counter
import copy
from dataclasses import FrozenInstanceError
from datetime import date, timedelta
import hashlib
import io
import json
import os
from pathlib import Path
import socket
from types import SimpleNamespace
import urllib.request  # Initialize ssl types before replacing socket in offline fixtures.
import zipfile

import pytest

from work.profit_1000_upgrade import candidate_scope_verify as v

RUN_ID, COMMIT = "123456789", "a" * 40


def encode(value):
    return (json.dumps(value, sort_keys=True, ensure_ascii=False, indent=2, allow_nan=False) + "\n").encode()


def forbidden(*args, **kwargs):
    raise AssertionError("no HTTP, collector, training, labels or writes during verification")


def fixture_scope(base_bytes, members):
    dates = {(date(2025, 1, 1) + timedelta(days=n)).strftime("%Y%m%d") for n in range(210)}
    dates.update(v.inputs.PREFLIGHT_T_DATES)
    dates = sorted(dates)
    assert len(dates) == 212
    codes = {day: [f"{600000 + j:06d}.SH" for j in range(8 if i < 48 else 9)] for i, day in enumerate(dates)}
    for day, code in v.PREFLIGHT: codes[day][0] = code
    return {"base_archive": {"sha256": hashlib.sha256(base_bytes).hexdigest(), "bytes": len(base_bytes), "synthetic_fixture": True},
        "frozen_manifest": {"rows": [], "synthetic_fixture": True}, "gap_dates": dates,
        "gap_candidate_codes": codes, "reused_dates": ["20250116"], "precoverage_dates": ["20241231"],
        "code_bindings": [{"path": name, "sha256": v.inputs._file_sha(v.CHECKOUT / name)} for name in sorted(v.inputs.CODE_PATHS)],
        "archive_file_bindings": [{"path": name, "sha256": hashlib.sha256(raw).hexdigest(), "bytes": len(raw)} for name, raw in members.items()]}


def binding(root, path):
    raw = path.read_bytes()
    return {"path": path.relative_to(root).as_posix(), "sha256": hashlib.sha256(raw).hexdigest(), "bytes": len(raw)}


def blank(day, code, status="NOT_REQUESTED_BUDGET_EXHAUSTED"):
    return {"trade_date": day, "ts_code": code, "request": v.source.request_contract(day, code),
        "preflight": (day, code) in v.PREFLIGHT, "api_calls": 0, "request_sequence": None,
        "status": status, "reason": None, "network_request_performed": False,
        "http_response_sha256": None, "http_response_bytes": None, "source_files": [], "rows": None}


def success(root, item, sequence, *, empty=False):
    day, code = item["trade_date"], item["ts_code"]
    raw = encode({"code": 0, "detail": "...", "data": {"fields": list(v.source.FIELDS),
        "items": [] if empty else [[code, day, "7.65999", 100, None, 7.1]], "has_more": False, "count": 0}})
    bodies = v.source.source_bytes(raw, day, code, request=item["request"], fetched_at_utc="2026-09-13T01:00:00Z", network_request_performed=True)
    paths = v.source.source_paths(root, day, code)
    for path, body in zip(paths, bodies):
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(body)
    item.update(api_calls=1, request_sequence=sequence, network_request_performed=True,
                http_response_sha256=hashlib.sha256(raw).hexdigest(), http_response_bytes=len(raw),
                status="CANDIDATE_TABLE_EMPTY" if empty else "CANDIDATE_TABLE_PRESENT", rows=0 if empty else 1,
                source_files=[binding(root, path) for path in paths])


def refresh(root, report, *, counts=True):
    rows = report["requests"]
    journal = sorted((r for r in rows if r["api_calls"]), key=lambda r: r["request_sequence"])
    (root / v.JOURNAL).write_bytes(b"".join(json.dumps(row, sort_keys=True).encode() + b"\n" for row in journal))
    report["source_files"] = sorted((b for r in rows for b in r["source_files"]), key=lambda b: b["path"])
    report["output_file_bindings"] = sorted((binding(root, path) for path in root.rglob("*") if path.is_file() and path.name != v.RECEIPT), key=lambda b: b["path"])
    if counts:
        report.update(api_calls=sum(r["api_calls"] for r in rows), qualified_new_source_pairs=sum(r["status"] in v.source.STATUSES for r in rows),
                      new_source_status_counts=dict(Counter(r["status"] for r in rows)))
    (root / v.RECEIPT).write_bytes(encode(report))


def verify(root, **overrides):
    return v.verify(root, **{"expected_run_id": RUN_ID, "expected_run_commit": COMMIT, **overrides})


@pytest.fixture
def artifact(tmp_path, monkeypatch):
    root = tmp_path / "collection"
    root.mkdir()
    members = {v.inputs.LABELS: encode({"as_of_date": "20260911", "rows": ["old outcomes must never be consumed"]}),
               "old/original.bin": b"\x00\xff preserve all members"}
    buffer = io.BytesIO()
    with zipfile.ZipFile(buffer, "w") as archive:
        for name, raw in members.items(): archive.writestr(name, raw)
    base_bytes = buffer.getvalue()
    (root / v.BASE).write_bytes(base_bytes)
    scope = fixture_scope(base_bytes, members)
    def read_base(path):
        assert Path(path) == root / v.BASE
        if Path(path).read_bytes() != base_bytes: raise ValueError("PINNED_BASE_ARCHIVE_CHANGED")
        return copy.deepcopy(scope)
    monkeypatch.setattr(v.inputs, "read_base_archive", read_base)
    monkeypatch.setattr(socket, "socket", forbidden)
    rows = [blank(day, code) for day in scope["gap_dates"] for code in scope["gap_candidate_codes"][day]]
    rows.sort(key=lambda r: (r["trade_date"], r["ts_code"]))
    assert len(rows) == 1860
    by_pair = {(r["trade_date"], r["ts_code"]): r for r in rows}
    for sequence, pair in enumerate(v.PREFLIGHT, 1): success(root, by_pair[pair], sequence)
    # Gap document deliberately follows collector's pretty JSON checksum,
    # whereas authority.frozen_manifest_sha256 uses compact historic checksum.
    manifest = {"schema_version": "dc20_candidate_auction_gap_manifest_v1", "base_archive": scope["base_archive"],
        "scope_counts": dict(v.inputs.COUNTS), "gap_dates": scope["gap_dates"], "gap_candidate_codes": scope["gap_candidate_codes"],
        "reused_dates": scope["reused_dates"], "precoverage_dates": scope["precoverage_dates"],
        "preflight_pairs": [list(p) for p in v.PREFLIGHT], "frozen_manifest_sha256": hashlib.sha256(encode(scope["frozen_manifest"])).hexdigest(),
        "old_outcomes_used_for_scope": False}
    (root / v.MANIFEST).write_bytes(encode(manifest))
    report = {"schema_version": v.SCHEMA, "status": "SOURCE_PAIRS_PARTIAL", "base_archive": scope["base_archive"],
        "source_policy_id": v.source.SOURCE_POLICY_ID, "scope_counts": dict(v.inputs.COUNTS),
        "preflight_pairs": [list(p) for p in v.PREFLIGHT], "preflight_passed": True,
        "eligible_as_real_collection": True, "callable_injected_for_test": False, "max_api_calls": 1860, "retries": 0,
        "elapsed_collection_seconds": 2980.1, "reused_base_source_dates": len(scope["reused_dates"]),
        "requests": rows, "execution_file_bindings": {name: v.inputs._file_sha(v.CHECKOUT / name) for name in v.inputs.CODE_PATHS | v.NEW_CODE},
        "observed_at_utc": "2026-09-13T01:01:00Z", "run_id": RUN_ID, "run_commit": COMMIT, **v.FLAGS}
    refresh(root, report)
    return root, report, scope


def test_independent_partial_replay_returns_private_immutable_authority(artifact, monkeypatch):
    root, report, scope = artifact
    from work.profit_1000_upgrade import candidate_scope_collect
    monkeypatch.setattr(candidate_scope_collect, "run_collection", forbidden)
    monkeypatch.setattr(candidate_scope_collect, "expected_contract", forbidden)
    for name in ("source_bytes",): monkeypatch.setattr(v.source, name, forbidden)
    monkeypatch.setattr(Path, "write_bytes", forbidden)
    monkeypatch.setattr(Path, "write_text", forbidden)
    value = verify(root)
    assert type(value) is v.VerifiedCandidateCollection
    assert value.root == root and value.source_only and not value.label_source_eligible
    assert value.gap_pairs == tuple(sorted((r["trade_date"], r["ts_code"]) for r in report["requests"]))
    assert value.successful_pairs == tuple(sorted(v.PREFLIGHT)) and len(value.source_bindings) == 4
    assert value.as_of_date == "20260911" and value.frozen_manifest_sha256 == v.inputs._manifest_sha(scope["frozen_manifest"])
    assert value.receipt_sha256 == hashlib.sha256((root / v.RECEIPT).read_bytes()).hexdigest()
    assert value.base_archive_sha256 == scope["base_archive"]["sha256"]
    assert len(value.base_file_bindings) == 2 and all("path" in b and "sha256" in b for b in value.base_file_bindings)
    assert value.assert_unchanged() is None
    assert v.reload_verified(value).receipt_sha256 == value.receipt_sha256
    with pytest.raises(FrozenInstanceError): value.source_only = False
    with pytest.raises(TypeError): value.source_bindings[0]["sha256"] = "0" * 64
    with pytest.raises(TypeError): value.scope["gap_candidate_codes"]["20250319"] = ()
    assert not hasattr(value, "__dict__")


