@pytest.mark.parametrize("kind", ["missing", "duplicate", "reorder", "code", "extra_key", "preflight_bool", "network_bool", "calls_bool", "status", "reason"])
def test_all_1860_requests_and_exact_fields_required(artifact, kind):
    root, report, _ = artifact
    rows = report["requests"]
    if kind == "missing": rows.pop()
    elif kind == "duplicate": rows[-1] = copy.deepcopy(rows[0])
    elif kind == "reorder": rows.reverse()
    elif kind == "code": rows[0]["ts_code"] = "600999.SH"
    elif kind == "extra_key": rows[0]["injected"] = True
    elif kind == "preflight_bool": rows[0]["preflight"] = 0
    elif kind == "network_bool": rows[0]["network_request_performed"] = 0
    elif kind == "calls_bool": rows[0]["api_calls"] = False
    elif kind == "status": rows[0]["status"] = "NO_FILL_SOURCE_ERROR"
    else: rows[0]["reason"] = "MADE_UP"
    refresh(root, report)
    with pytest.raises(ValueError): verify(root)


@pytest.mark.parametrize("kind", ["STK", "offset", "wrongstock", "fullmarket", "fields", "future"])
def test_request_scope_cannot_be_rewritten(artifact, kind):
    root, report, _ = artifact
    row = report["requests"][0]
    if kind in ("STK", "offset"): row["request"]["params"]["ts_type" if kind == "STK" else "offset"] = "STK"
    elif kind == "wrongstock": row["request"]["params"]["ts_code"] = "600999.SH"
    elif kind == "fullmarket": del row["request"]["params"]["ts_code"]
    elif kind == "future": row["request"]["params"]["trade_date"] = "20260914"
    else: row["request"]["fields"].reverse()
    refresh(root, report)
    with pytest.raises(ValueError): verify(root)


@pytest.mark.parametrize("kind", ["rowcount", "http_sha", "http_bytes", "success_reason", "source_order", "sequence_duplicate", "sequence_swap"])
def test_success_requires_replayed_source_http_meta_and_request_sequence(artifact, kind):
    root, report, _ = artifact
    present = [r for r in report["requests"] if r["api_calls"]]
    row = present[0]
    if kind == "rowcount": row["rows"] = 0
    elif kind == "http_sha": row["http_response_sha256"] = "1" * 64
    elif kind == "http_bytes": row["http_response_bytes"] += 1
    elif kind == "success_reason": row["reason"] = "ERROR"
    elif kind == "source_order": row["source_files"].reverse()
    elif kind == "sequence_duplicate": present[1]["request_sequence"] = row["request_sequence"]
    else: present[0]["request_sequence"], present[1]["request_sequence"] = present[1]["request_sequence"], present[0]["request_sequence"]
    refresh(root, report)
    with pytest.raises(ValueError): verify(root)


def test_complete_empty_regular_pair_is_source_not_price_authority(artifact):
    root, report, _ = artifact
    row = next(r for r in report["requests"] if not r["preflight"])
    success(root, row, 3, empty=True)
    refresh(root, report)
    value = verify(root)
