def test_full_1860_source_pairs_replay_without_filtering_empty_or_numeric_errors(artifact):
    root, report, _ = artifact
    sequence = 2
    for row in report["requests"]:
        if row["preflight"]: continue
        sequence += 1
        success(root, row, sequence, empty=sequence % 2 == 0)
    report["status"] = "SOURCE_PAIRS_COLLECTED"
    refresh(root, report)
    value = verify(root)
    assert value.status == "SOURCE_PAIRS_COLLECTED" and len(value.successful_pairs) == 1860
    assert len(value.source_bindings) == 3720 and len(value._output_bindings) == 3724


@pytest.mark.skipif(not os.environ.get("DC20_CANDIDATE_REAL_BASE"), reason="explicit real pinned ZIP integration opt-in")
def test_real_base_zero_call_blocked_end_to_end(tmp_path, monkeypatch):
    from work.profit_1000_upgrade import candidate_scope_collect as collector
    monkeypatch.setenv("GITHUB_RUN_ATTEMPT", "1")
    monkeypatch.setenv("GITHUB_RUN_ID", RUN_ID)
    monkeypatch.setenv("GITHUB_SHA", COMMIT)
    monkeypatch.setattr(collector, "official_call", forbidden)
    output = tmp_path / "real-base-zero-call"
    result = collector.run_collection(Path(os.environ["DC20_CANDIDATE_REAL_BASE"]), output, token="")
    assert result["api_calls"] == 0 and result["status"] == "PREFLIGHT_BLOCKED"
    value = verify(output)
    assert value.base_archive_sha256 == v.inputs.BASE_SHA256 and len(value.gap_pairs) == 1860
    assert value.successful_pairs == () and len(value.base_file_bindings) == 7676 and value.as_of_date == "20260911"
    value.assert_unchanged()
